/*
 * A116547  Permutation of natural numbers generated by 5-rowed array shown
 *          below.
 * https://oeis.org/A116547
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   Enumerate the infinite matrix M[r][c] = 5*c + r (0 ≤ r ≤ 4)
 *            along diagonals (r + c = d). For each diagonal d, output the
 *            cells with r = 0 … min(4, d) in that order. The nth term is a(n)
 *            = 5*(d - r) + r, where d is the diagonal index of the nth
 *            element and r = (position of the element within that...
 * Range:     u8 n <= 250, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n <= 15) {
        idx_t rem = n;
        for (idx_t d = 0; ; ++d) {
            idx_t cnt = (d <= 4) ? d + 1 : 5;
            if (rem <= cnt) {
                idx_t r = rem - 1;
                seq_t c = (seq_t)d - (seq_t)r;
                return (seq_t)5 * c + (seq_t)r;
            }
            rem -= cnt;
        }
    } else {
        idx_t rem = n - 15;           /* m = n – 15,  m ≥ 1 */
        idx_t t   = (rem - 1) / 5;     /* number of full diagonals after d = 5 */
        idx_t d   = 5 + t;
        idx_t r   = (rem - 1) % 5;     /* 0 … 4 */
        seq_t c   = (seq_t)d - (seq_t)r;
        return (seq_t)5 * c + (seq_t)r;
    }
}
